fn withdraw(a: Account, amt: Int) -> Account ! fail[TxErr]
= do
  if amt <= 0 then raise Invalid
  if amt > a.balance then raise Insufficient{short: amt - a.balance}
  Account{id: a.id, balance: a.balance - amt}

test t16_ok = catch withdraw({id: "a", balance: 10}, 3) == Account{id: "a", balance: 7}
  | _ => false
test t16_inv = catch withdraw({id: "a", balance: 10}, 0) == Account{id: "a", balance: 10}
  | Invalid => true
  | Insufficient{short: _} => false
test t16_short = catch withdraw({id: "a", balance: 10}, 15) == Account{id: "a", balance: 10}
  | Invalid => false
  | Insufficient{short} => short == 5

fn mirror(t: Tree) -> Tree
= match t
  | Leaf => Leaf
  | Node{left, value, right} => Node{left: mirror(right), value: value, right: mirror(left)}

test mirror_leaf = mirror(Leaf) == Leaf
test mirror_some = mirror(Node{left: Node{left: Leaf, value: 2, right: Leaf}, value: 1, right: Leaf}) == Node{left: Leaf, value: 1, right: Node{left: Leaf, value: 2, right: Leaf}}

fn word_lengths(s: Str) -> List[Int]
= do
  var words = s.split(" ")
  var filtered = words.filter(w => not w.is_empty)
  filtered.map(w => w.len)

fn partition[A](xs: List[A], f: A -> Bool) -> (List[A], List[A])
= do
  var true_list = []
  var false_list = []
  for x in xs do
    if f(x) then true_list := true_list.push(x)
    else false_list := false_list.push(x)
  (true_list, false_list)

fn insert(t: Tree, x: Int) -> Tree
= match t
  | Leaf => Node{left: Leaf, value: x, right: Leaf}
  | Node{left, value, right} =>
    if x < value then Node{left: insert(left, x), value, right}
    else if x > value then Node{left, value, right: insert(right, x)}
    else t

fn step(v: Vending, a: Action) -> (Vending, Str)
= match (v, a)
  | (Idle, Coin{cents}) => (HasCoins{cents}, "")
  | (HasCoins{cents: c}, Coin{cents: added}) => (HasCoins{cents: c + added}, "")
  | (Idle, Buy{price}) => (Idle, "need " + price.str)
  | (HasCoins{cents: c}, Buy{price}) =>
    if c >= price then (Idle, "vend change " + (c - price).str)
    else (HasCoins{cents: c}, "need " + (price - c).str)
  | (Idle, Refund) => (Idle, "refund 0")
  | (HasCoins{cents: c}, Refund) => (Idle, "refund " + c.str)

fn push_cmd(stack: List[Int], parts: List[Str]) -> List[Int] ! fail[CmdErr]
= if parts.len < 2 then raise MissingArg{cmd: "push"}
  else match parts[1].to_int
    | some(v) => stack.push(v)
    | none => raise MissingArg{cmd: "push"}

fn add_cmd(stack: List[Int]) -> List[Int] ! fail[CmdErr]
= if stack.len < 2 then raise MissingArg{cmd: "add"}
  else stack.take(stack.len - 2).push(stack[stack.len - 1] + stack[stack.len - 2])

fn pop_cmd(stack: List[Int]) -> List[Int] ! fail[CmdErr]
= if stack.is_empty then raise MissingArg{cmd: "pop"}
  else stack.take(stack.len - 1)

fn exec(stack: List[Int], cmd: Str) -> List[Int] ! fail[CmdErr]
= do
  parts = cmd.split(" ")
  head = parts.first.or("")
  if head == "push" then push_cmd(stack, parts)
  else if head == "pop" then pop_cmd(stack)
  else if head == "add" then add_cmd(stack)
  else raise Unknown{cmd: head}

